(()=>{
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const style=document.createElement('style');style.textContent=`.portfolio-return{position:fixed!important;z-index:2147482000!important;left:18px!important;bottom:18px!important;display:flex!important;align-items:center!important;gap:9px!important;padding:10px 14px!important;text-decoration:none!important;font:14px/1.3 'PingFang SC','Microsoft YaHei',sans-serif!important;letter-spacing:.04em!important;color:#183053!important;background:linear-gradient(135deg,#faffffed,#d7e5f3ed)!important;border:1px solid #a4b5c8!important;border-radius:3px!important;box-shadow:0 3px 12px #0002!important;backdrop-filter:blur(12px)!important;transition:box-shadow .25s,transform .25s!important}.portfolio-return:hover,.portfolio-return:focus-visible{box-shadow:0 0 0 2px #839fff80,0 0 22px #83ffff6b!important;transform:translateY(-2px)!important;outline:2px solid #496aff!important;outline-offset:3px!important}.portfolio-return-disc{width:20px!important;height:20px!important;border-radius:50%!important;background:conic-gradient(#b4c5d9,#f5fcff,#849ebd,#edfaff,#b4c5d9)!important;border:1px solid #8395ac!important;display:grid!important;place-items:center!important;flex:0 0 auto!important}.portfolio-return-disc:after{content:''!important;display:block!important;width:4px!important;height:4px!important;background:#234665!important;border-radius:50%!important}.portfolio-return:hover .portfolio-return-disc{animation:portfolio-spin 3s linear infinite!important}@keyframes portfolio-spin{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.portfolio-return-disc{animation:none!important}}@media(max-width:600px){.portfolio-return{left:10px!important;bottom:12px!important;padding:9px 11px!important;font-size:13px!important}}`;document.head.append(style);
 const link=document.createElement('a');link.className='portfolio-return';link.href='/#catalog';link.setAttribute('aria-label','返回作品集的唱片目录');link.innerHTML='<span class="portfolio-return-disc" aria-hidden="true"></span><span>返回目录</span>';document.body.append(link);
 document.querySelectorAll('video').forEach(v=>{if(v.autoplay&&!v.muted)v.muted=true;if(!v.autoplay)v.preload='metadata';if(reduced&&v.autoplay)v.pause()});
 if(document.body.classList.contains('source-page')){
  const extra=document.createElement('style');extra.textContent=`.portfolio-strip{border:0!important;background:none!important;display:block!important;padding:0!important;width:100%!important;cursor:zoom-in!important;line-height:0!important}.portfolio-strip:focus-visible{outline:3px solid #62e9e1!important;outline-offset:-3px!important}.portfolio-image-dialog{padding:0!important;border:1px solid #567596!important;border-radius:4px!important;background:#101c29!important;width:min(96vw,1500px)!important;max-width:96vw!important;height:94svh!important;max-height:94svh!important;color:white!important}.portfolio-image-dialog::backdrop{background:#07101bec!important;backdrop-filter:blur(8px)!important}.portfolio-dialog-toolbar{height:50px!important;display:flex!important;align-items:center!important;justify-content:space-between!important;gap:14px!important;padding:8px 16px!important;font:14px/1.4 'PingFang SC',sans-serif!important}.portfolio-dialog-toolbar button{border:1px solid #7b96b0!important;background:#253b53!important;color:white!important;padding:6px 12px!important;border-radius:3px!important;font:inherit!important;cursor:pointer!important}.portfolio-dialog-toolbar button:focus-visible{outline:2px solid #68e7e9!important;outline-offset:3px!important}.portfolio-dialog-stage{height:calc(100% - 50px)!important;overflow:auto!important;overscroll-behavior:contain!important}.portfolio-dialog-stage img{width:100%!important;height:auto!important;display:block!important;max-width:none!important;margin:auto!important}.portfolio-dialog-stage.native img{width:var(--native-width)!important}.portfolio-source-hint{position:fixed!important;right:18px!important;bottom:18px!important;z-index:10!important;color:#d9eaff!important;background:#152f4bd9!important;border:1px solid #486b89!important;padding:8px 12px!important;border-radius:3px!important;font:13px/1.4 'PingFang SC',sans-serif!important;pointer-events:none!important}@media(max-width:600px){.portfolio-source-hint{right:10px!important;bottom:12px!important;font-size:12px!important}}`;document.head.append(extra);
  const dialog=document.createElement('dialog');dialog.className='portfolio-image-dialog';dialog.innerHTML='<div class="portfolio-dialog-toolbar"><span>原稿细节</span><div><button class="portfolio-native-toggle" aria-pressed="false">放大阅读</button> <button class="portfolio-dialog-close" aria-label="关闭原稿放大窗口">关闭</button></div></div><div class="portfolio-dialog-stage"><img alt=""></div>';dialog.setAttribute('aria-label','查看原稿细节');document.body.append(dialog);
  const stage=dialog.querySelector('.portfolio-dialog-stage'),detail=stage.querySelector('img'),zoom=dialog.querySelector('.portfolio-native-toggle');let last;
  zoom.onclick=()=>{const native=stage.classList.toggle('native');zoom.textContent=native?'适合屏幕':'放大阅读';zoom.setAttribute('aria-pressed',String(native))};dialog.querySelector('.portfolio-dialog-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog.addEventListener('close',()=>last?.focus({preventScroll:true}));
  document.querySelectorAll('main>img').forEach(image=>{const button=document.createElement('button');button.className='portfolio-strip';button.setAttribute('aria-label','点击放大：'+image.alt);image.before(button);button.append(image);button.onclick=()=>{last=button;detail.src=image.src;detail.alt=image.alt;stage.classList.remove('native');stage.style.setProperty('--native-width',Math.max(image.naturalWidth,1200,innerWidth*1.6)+'px');zoom.textContent='放大阅读';zoom.setAttribute('aria-pressed','false');dialog.showModal();stage.scrollTop=0;stage.scrollLeft=0;dialog.querySelector('.portfolio-dialog-close').focus()}});
  const hint=document.createElement('span');hint.className='portfolio-source-hint';hint.textContent='点击画面 · 放大阅读';document.body.append(hint);
 }
})();
